#pragma once

#include <stddef.h>
#include <stdint.h>
#include <string.h>

// AI: below section was generated by an AI

/*
 * Language-independent word clock logic.
 *
 * Nothing in here knows a language: the front panel layout, the hour words and
 * the phrase for every 5 minutes all come from the settings. All texts are
 * UTF-8, every character of the layout except the row separator is one LED.
 * The characters '1' to '4' in the layout are minute dots: dot n is lit when
 * minute % 5 >= n.
 */
namespace WordClock {

constexpr uint8_t SLOTS = 12;          // one phrase per 5 minutes
constexpr uint8_t MAX_ROWS = 32;
constexpr uint8_t MAX_WORD_REPORT = 24; // bytes kept of a word that was not found
constexpr char ROW_SEPARATOR = '|';
constexpr char LIST_SEPARATOR = ',';
constexpr char OCCURRENCE_MARK = '#';
constexpr char FIRST_DOT = '1';
constexpr char LAST_DOT = '4';

struct Settings {
  const char* layout;          // rows separated by ROW_SEPARATOR
  const char* prefix;          // e.g. "ES IST"
  const char* hours;           // words for 1..12, separated by LIST_SEPARATOR
  const char* fullHours;       // optional words used at the full hour, empty entries fall back to hours
  const char* phrases[SLOTS];  // phrase for :00, :05, ... :55 with {h}, {n}, {H} placeholders
  bool showPrefix;
  bool meander;
};

// start[r] is the first LED of row r, start[count] is the number of LEDs (letters and minute dots)
struct Rows {
  uint16_t start[MAX_ROWS + 1];
  uint8_t count;
};

inline bool isContinuation(char c) { return (static_cast<uint8_t>(c) & 0xC0) == 0x80; }

// number of characters (not bytes) in a UTF-8 text
inline uint16_t charCount(const char* text, size_t len) {
  uint16_t count = 0;
  for (size_t i = 0; i < len; i++) if (!isContinuation(text[i])) count++;
  return count;
}

// Splits the layout into rows. Returns false for a layout without letters or with too many rows.
inline bool parseRows(const char* layout, Rows& rows) {
  uint16_t leds = 0;
  rows.count = 0;
  rows.start[0] = 0;
  for (const char* p = layout; *p; p++) {
    if (*p == ROW_SEPARATOR) {
      if (++rows.count >= MAX_ROWS) return false;
      rows.start[rows.count] = leds;
    } else if (!isContinuation(*p)) {
      leds++;
    }
  }
  rows.start[++rows.count] = leds;
  return leds > 0;
}

// Converts a LED in reading order to its position on the strip: with meander wiring every odd row runs backwards.
inline uint16_t physicalLed(uint16_t led, const Rows& rows, bool meander) {
  if (!meander) return led;
  uint8_t row = 0;
  while (row + 1 < rows.count && led >= rows.start[row + 1]) row++;
  if (row % 2 == 0) return led;
  return rows.start[row] + rows.start[row + 1] - 1 - led;
}

// LED (in reading order) of the character at byte offset pos of the layout
inline uint16_t ledAt(const char* layout, int pos) {
  uint16_t led = 0;
  for (int p = 0; p < pos; p++) if (layout[p] != ROW_SEPARATOR && !isContinuation(layout[p])) led++;
  return led;
}

/*
 * Finds a word in the layout and returns its byte offset, or -1.
 * occurrence > 0 selects the n-th match in the whole layout, otherwise the first match at or after byte offset from.
 * A match never spans two rows, because a word cannot contain the row separator.
 */
inline int findWord(const char* layout, const char* word, size_t len, int from, uint8_t occurrence) {
  if (len == 0 || memchr(word, ROW_SEPARATOR, len)) return -1; // a word must stay within one row
  uint8_t seen = 0;
  for (int p = occurrence ? 0 : from; layout[p]; p++) {
    if (isContinuation(layout[p]) || strncmp(layout + p, word, len) != 0) continue;
    if (!occurrence || ++seen == occurrence) return p;
  }
  return -1;
}

// Gets entry index (0-based) of a comma-separated list without surrounding spaces. Returns false if it is missing or empty.
inline bool listEntry(const char* list, uint8_t index, const char*& start, size_t& len) {
  const char* p = list;
  for (uint8_t i = 0; i < index; i++) {
    p = strchr(p, LIST_SEPARATOR);
    if (!p) return false;
    p++;
  }
  while (*p == ' ') p++;
  const char* end = p;
  while (*end && *end != LIST_SEPARATOR) end++;
  while (end > p && end[-1] == ' ') end--;
  start = p;
  len = end - p;
  return len > 0;
}

/*
 * Builds the LED mask for one time. Words are searched in the order of the sentence, each one after the previous match,
 * so a word that appears several times on the panel is taken from the right place. WORD#2 selects the 2nd occurrence
 * in the whole panel instead, for cases where the reading order cannot decide (e.g. DREI inside DREIVIERTEL).
 */
class Composer {
  public:
    // mask needs one byte per LED of the layout, nullptr only checks that all words are found.
    // text (optional) receives the lit words separated by spaces.
    Composer(const Settings& settings, const Rows& rows, uint8_t* mask, char* text = nullptr, size_t textSize = 0)
      : _s(settings), _rows(rows), _mask(mask), _text(textSize ? text : nullptr), _textSize(textSize) {}

    // Lights the words for hour12 (1..12) and minute (0..59). Returns false if a word was not found (see missing).
    bool compose(uint8_t hour12, uint8_t minute) {
      if (_mask) memset(_mask, 0, _rows.start[_rows.count]);
      if (_text) _text[0] = '\0';
      _from = 0;
      missing[0] = '\0';
      bool ok = true;
      if (_s.showPrefix) ok &= placeText(_s.prefix, strlen(_s.prefix), hour12, false);
      const char* phrase = _s.phrases[(minute / 5) % SLOTS];
      ok &= placeText(phrase, strlen(phrase), hour12, true);
      if (_mask) placeDots(minute % 5);
      return ok;
    }

    char missing[MAX_WORD_REPORT + 1] = ""; // first word that was not found

  private:
    const Settings& _s;
    const Rows& _rows;
    uint8_t* _mask;
    char* _text;
    size_t _textSize;
    int _from = 0; // byte offset where the next word is searched

    // Lights the minute dots of the layout: dot '1' for dots >= 1, dot '2' for dots >= 2, and so on.
    void placeDots(uint8_t dots) {
      uint16_t led = 0;
      for (const char* p = _s.layout; *p; p++) {
        if (*p == ROW_SEPARATOR || isContinuation(*p)) continue;
        if (*p >= FIRST_DOT && *p <= LAST_DOT && *p - FIRST_DOT < dots) _mask[physicalLed(led, _rows, _s.meander)] = 1;
        led++;
      }
    }

    // Appends a lit word to the optional text, cut at a character boundary if the buffer is full.
    void appendText(const char* word, size_t n) {
      if (!_text) return;
      size_t used = strlen(_text);
      if (used > 0 && used + 1 < _textSize) _text[used++] = ' ';
      if (n > _textSize - 1 - used) {
        n = _textSize - 1 - used;
        while (n > 0 && isContinuation(word[n])) n--;
      }
      memcpy(_text + used, word, n);
      _text[used + n] = '\0';
    }

    // Lights the space-separated words of text. With expand, {h}, {n} and {H} are replaced by the current hour,
    // the next hour and the current hour's full-hour word.
    bool placeText(const char* text, size_t len, uint8_t hour12, bool expand) {
      bool ok = true;
      const char* end = text + len;
      for (const char* p = text; p < end;) {
        while (p < end && *p == ' ') p++;
        const char* word = p;
        while (p < end && *p != ' ') p++;
        const size_t n = p - word;
        if (n == 0) continue;
        if (expand && n == 3 && word[0] == '{' && word[2] == '}' && (word[1] == 'h' || word[1] == 'n' || word[1] == 'H')) {
          const uint8_t hour = (word[1] == 'n') ? hour12 % 12 + 1 : hour12;
          const char* entry;
          size_t entryLen;
          if ((word[1] == 'H' && listEntry(_s.fullHours, hour - 1, entry, entryLen)) || listEntry(_s.hours, hour - 1, entry, entryLen)) {
            ok &= placeText(entry, entryLen, hour12, false);
          } else {
            report(word, n);
            ok = false;
          }
          continue;
        }
        ok &= placeWord(word, n);
      }
      return ok;
    }

    // Lights one word, with an optional #n suffix for the n-th occurrence.
    bool placeWord(const char* word, size_t n) {
      size_t len = n;
      uint8_t occurrence = 0;
      for (size_t i = n; i-- > 1;) {
        if (word[i] < '0' || word[i] > '9') {
          if (word[i] == OCCURRENCE_MARK && i + 1 < n) {
            unsigned value = 0;
            for (size_t j = i + 1; j < n; j++) value = value * 10 + (word[j] - '0');
            if (value > 0 && value <= UINT8_MAX) {
              occurrence = value;
              len = i;
            }
          }
          break;
        }
      }
      const int pos = findWord(_s.layout, word, len, _from, occurrence);
      if (pos < 0) {
        report(word, n);
        return false;
      }
      _from = pos + len;
      appendText(word, len);
      if (_mask) {
        const uint16_t first = ledAt(_s.layout, pos);
        const uint16_t count = charCount(word, len);
        for (uint16_t i = 0; i < count; i++) _mask[physicalLed(first + i, _rows, _s.meander)] = 1;
      }
      return true;
    }

    // Keeps the first word that was not found (shortened to MAX_WORD_REPORT bytes) for the error message.
    void report(const char* word, size_t n) {
      if (missing[0]) return;
      if (n > MAX_WORD_REPORT) n = MAX_WORD_REPORT;
      while (n > 0 && isContinuation(word[n])) n--; // do not cut a character in half
      memcpy(missing, word, n);
      missing[n] = '\0';
    }
};

} // namespace WordClock

// AI: end
